package com.smartcanteen.controller;
import com.smartcanteen.entity.*;import com.smartcanteen.repository.UserRepository;import com.smartcanteen.security.JwtService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
public record Register(@NotBlank String fullName,@Email @NotBlank String email,@NotBlank String studentId,@Size(min=8,max=72) String password){} public record Login(@Email @NotBlank String email,@NotBlank String password){} private Map<String,Object> response(AppUser u){return Map.of("token",jwt.generate(u),"user",Map.of("id",u.getId(),"fullName",u.getFullName(),"email",u.getEmail(),"studentId",u.getStudentId()==null?"":u.getStudentId(),"role",u.getRole().name()));}
@PostMapping("/register") public Map<String,Object> register(@Valid @RequestBody Register r){String email=r.email().trim().toLowerCase();if(users.existsByEmailIgnoreCase(email))throw new IllegalArgumentException("Email is already registered.");if(users.existsByStudentId(r.studentId()))throw new IllegalArgumentException("Student ID is already registered.");AppUser u=new AppUser();u.setFullName(r.fullName().trim());u.setEmail(email);u.setStudentId(r.studentId().trim());u.setPasswordHash(encoder.encode(r.password()));u.setRole(Role.STUDENT);return response(users.save(u));}
@PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody Login r){AppUser u=users.findByEmailIgnoreCase(r.email().trim()).orElseThrow(()->new IllegalArgumentException("Invalid email or password."));if(!u.isActive()||!encoder.matches(r.password(),u.getPasswordHash()))throw new IllegalArgumentException("Invalid email or password.");return response(u);}
@GetMapping("/me") public Map<String,Object> me(org.springframework.security.core.Authentication a){AppUser u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();return Map.of("id",u.getId(),"fullName",u.getFullName(),"email",u.getEmail(),"role",u.getRole().name());}}
